// dismiss banners if present, then search
try { phi.click("#kmx-privacy-banner-close-button"); } catch(e) {}
try { phi.click("button=Got it"); } catch(e) {}
const o = phi.observe({ within: "header" });
const box = o.nodes.find(n => n.role === "searchbox" || /search make/i.test(n.name));
const filled = box ? phi.fill(box.ref, "2022 Tesla Model 3") : null;
phi.sleep(1200);
const after = phi.observe();
return { box, filled, nodes: after.nodes.slice(0, 30), url: after.url };

const sub = phi.click("#header-search-button");
phi.sleep(2500);
const u = phi.observe({ viewportOnly: false, maxElements: 60 });
return { sub: { url: sub.url, navigated: sub.navigated }, url: u.url, title: u.title, nodes: u.nodes.slice(0, 50), text: u.text.slice(0, 1200) };

const u = phi.observe({ viewportOnly: true, maxElements: 40 });
const res = phi.query("a[href*='/car/']", { fields: ["href", "text"], limit: 10 });
const tiles = phi.query("#kmx-car-tile-menu-button-70280293", { limit: 1 });
// gather any headings/results count text
const txt = phi.text();
return { url: u.url, viewportNodes: u.nodes.slice(0, 25), linkSample: res, textHead: txt.slice(0, 1800) };

const o = phi.observe({ viewportOnly: true, maxElements: 40 });
const link = o.nodes.find(n => n.role === "link" && n.name === "2022 Tesla Model 3");
const before = phi.tabs.list();
const c = phi.click(link.ref);
phi.sleep(3000);
const after = phi.tabs.list();
return { link, c: { url: c.url, navigated: c.navigated, download: c.download }, before, after, url: phi.observe({maxElements:5}).url };

const t = phi.text();
const u = phi.observe({ viewportOnly: false, maxElements: 60 });
return { url: u.url, title: u.title, len: t.length, head: t.slice(0, 3000), nodes: u.nodes.slice(0, 40) };

